import { remainingEntryLedgers } from './remaining-content-ledgers';

/**
 * 研究层：把「文章写了什么」与「为什么能这样写」放在同一处。
 *
 * 这不是书目清单。每个 source 都必须说明实际核对到的定位和它支持的论断；
 * 文字的性质也被显式标出，避免把解释或例子伪装为原文事实。
 */

export type ContentKind = '原文入口' | '概括' | '解释性重构' | '原创例子' | '争议性判断';

/**
 * 一条来源的核验状态。
 *
 * 这个字段以前的类型是字面量 `true`，也就是说「待核验」在类型上根本无法表达；
 * 渲染层又把「已核验」三个字硬编码在 JSX 里，谁都不读这个字段。结果是本轮
 * 审查在标着「已核验」的来源里查出了 8 个 404 链接和一批对不上的章节定位。
 *
 * 现在三种状态都能表达，页面显示的就是这个值：
 *   - verified：本轮实际打开过，标题与定位对得上；
 *   - pending：还没有逐段核对，或定位仍待确认；
 *   - broken：链接已失效或指向的内容与论断不符，正文引用它即为已知缺陷。
 */
export type SourceCheckState = 'verified' | 'pending' | 'broken';

export const sourceCheckLabels: Record<SourceCheckState, string> = {
  verified: '已核验',
  pending: '待核验',
  broken: '链接失效｜待更换',
};

export type LedgerSource = {
  id: string;
  title: string;
  /*
    '研究论文' 是 2026-09-20 加的：此前只有 '原典 | 学术综述 | 制度文件' 三类，
    单篇署名的期刊论文（以及 SEP 词条的中译本）无处可归，只能挤进「学术综述」，
    而综述与单篇论文对读者的意义不同——前者给的是领域现状，后者给的是一个
    可被反驳的具体主张。中文资料大量是后者，挤在一起会看不出这一点。
  */
  kind: '原典' | '学术综述' | '研究论文' | '制度文件';
  url: string;
  locator: string;
  checked: SourceCheckState;
  /** 最近一次实际打开并核对这条来源的日期。pending 的来源可以省略。 */
  checkedOn?: string;
  supports: string;
};

export type LedgerParagraph = {
  kind: ContentKind;
  text: string;
  sourceIds?: string[];
};

export type ReviewFinding = {
  location: string;
  issue: string;
  evidence: string;
  revision: string;
};

export type CoreEntryLedger = {
  status: '核验正文｜自审完成';
  scope: string;
  /**
   * 具体入口：读者在读到任何抽象说法之前先看到的那个情形。
   *
   * 加这个字段的原因是本轮复审的结论：每一页原来都从「问题为何会出现」的
   * 概括开始，而那一段的第一句往往已经在用本页要解释的术语（「两种直觉的
   * 冲突」「规范性来源」「可归属性」）。初学者在还没有画面的时候先拿到
   * 一个抽象判断，只能猜。
   *
   *   - scene：一个具体、可想象的情形。只呈现处境，不下判断、不引入术语。
   *   - turn：从这个情形逼出本页要处理的问题，并说明它为什么不好回答。
   *
   * data.json 里那个 `example` 字段不能代替它：有精读层或思想实验的页面
   * 根本不渲染 example（见 node-content.tsx 的三分支），41 个条目页里有
   * 大半从来没显示过自己的例子。
   */
  entry?: {
    scene: string;
    turn: string;
  };
  /**
   * 本页默认读者已经知道的东西。
   *
   * 关系层的 `prerequisite` 说的是整页依赖整页（「读 A 之前先读 B」），全库
   * 只有十二条，而且同一对节点之间只能有一条边——自由与心灵、好生活与对的
   * 行动这些相邻页之间登记的是「易混辨析」，那条信息本身也有用，不该为了
   * 挂一个前置把它换掉。
   *
   * 所以真正缺的是更细的一层：本页会用到、但要到别的页面才展开的那几个
   * 具体区分。每条写三件事——
   *   - point：用到的是哪一个区分或概念（不是「建议先读上一章」）；
   *   - recap：一句话回顾，让不想跳转的读者也能接着往下读；
   *   - nodeId：在哪一页展开（可选；纯属常识性铺垫时可以不给）。
   *
   * 写不出 recap 就说明这一条其实不必前置；宁可在正文里就地解释。
   */
  assumed?: { point: string; recap: string; nodeId?: string }[];
  sectionHeadings?: Partial<{
    origin: string;
    boundaries: string;
    objections: string;
    confusions: string;
    historicalContext: string;
    /** 「主要立场」在方法页上并不合适——那里的三项不是三个互斥阵营。 */
    positions: string;
  }>;
  /**
   * 立场区块的导语。
   *
   * 只有需要先说明「这几项是什么关系」的条目才写。逻辑页是典型：演绎、归纳与
   * 解释性推断不是三选一，而这句纠正原本埋在第三张卡片论证路径的最后一步，
   * 读者要先读完三张编号 01/02/03、各带「反对意见」标签的卡片才可能看到。
   */
  positionsIntro?: string;
  origin: LedgerParagraph[];
  boundaries: LedgerParagraph[];
  objections: LedgerParagraph[];
  confusions: LedgerParagraph[];
  /**
   * 回到问题：读完这一页之后能说什么、还不能说什么。
   *
   * 不是把标题和术语再列一遍。四问各自独立：
   *   - question：用不含本页术语的普通话把核心问题重述一遍；
   *   - split：主要回答为什么不同——分歧落在哪一个前提、判准或推理步骤上；
   *   - settled：现在可以确定什么（通常是若干区分，而不是某一方胜出）；
   *   - open：还不能确定什么，以及卡在哪里。
   *
   * 「主要回答为什么不同」这一问是本轮加的重点：原来的页尾只有「带着问题
   * 继续读」，读者读完十几个区块之后没有任何地方帮他把分歧点收拢回来。
   */
  takeaway?: {
    question: string;
    split: string;
    settled: string;
    open: string;
  };
  historicalContext: { nodeId: string; label: string; note: string }[];
  sources: LedgerSource[];
  review: {
    mode: '自审（尚未独立复审）';
    checkedOn: string;
    findings: ReviewFinding[];
    remaining: string[];
    adjacentImpact: string;
    nextPriority: string;
  };
};

